import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"第一册：英语初阶 · Lesson 85 Paris in the spring","description":"学习 have been to 与过去时间，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 85 Paris in the spring","description":"学习 have been to 与过去时间，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 have been to 与过去时间，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 84 Have you had ...?","link":"/life/english/new-concept/book-1/unit-04/lesson-084"},"next":{"text":"第一册：英语初阶 · Lesson 86 What have you done?","link":"/life/english/new-concept/book-1/unit-04/lesson-086"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 84 Have you had ...?","link":"/life/english/new-concept/book-1/unit-04/lesson-084"},"next":{"text":"第一册：英语初阶 · Lesson 86 What have you done?","link":"/life/english/new-concept/book-1/unit-04/lesson-086"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-04/lesson-085.md","filePath":"life/english/new-concept/book-1/unit-04/lesson-085.md"}'),i={name:"life/english/new-concept/book-1/unit-04/lesson-085.md"};function s(l,e,r,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-lesson-85-paris-in-the-spring" tabindex="-1">第一册：英语初阶 · Lesson 85 Paris in the spring <a class="header-anchor" href="#第一册-英语初阶-·-lesson-85-paris-in-the-spring" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 85 Paris in the spring&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-04/overview">单元 4</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-086">配套课 Lesson 86</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>表达旅行经历并补充具体时间 本课要掌握have been to 与过去时间，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。先根据情境判断为什么要这样问或这样说，再看语言形式。</p><p>本课为情景学习；完成后进入相邻偶数课进行句型迁移。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>ever</td><td>/ˈevə/</td><td>adv.</td><td>曾经</td><td>have you ever</td></tr><tr><td>never</td><td>/ˈnevə/</td><td>adv.</td><td>从未</td><td>have never been</td></tr><tr><td>visit</td><td>/ˈvɪzɪt/</td><td>v.</td><td>参观；拜访</td><td>visit a city</td></tr><tr><td>trip</td><td>/trɪp/</td><td>n.</td><td>旅行</td><td>a short trip</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>have been to — 去过而已返回</li><li>have gone to — 已去尚未返回</li></ul><h2 id="语法讲解-have-been-to-与过去时间" tabindex="-1">语法讲解：have been to 与过去时间 <a class="header-anchor" href="#语法讲解-have-been-to-与过去时间" aria-label="Permalink to &quot;语法讲解：have been to 与过去时间&quot;">​</a></h2><p>have been to 表示去过并已返回的经历；have gone to 通常表示去了且尚未返回。谈经验可用现在完成时，补充明确结束的日期或年份时通常改一般过去时。I have been to Rome 与 I went there in 2022 可在一段话中衔接。不能把现在完成时直接与 yesterday 等已结束时间机械拼接。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>I have been to Vienna twice.</p></blockquote><p>我去过维也纳两次。</p><p>Have been to 表过去去过且已经返回；twice 说明经历次数，不给出具体已结束的日期。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>谈仍未回来的人用 has gone；不要把 gone 和 been 都译为无差别的“去过”。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“I have been to Vienna twice.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I have been to Vienna twice. Rita has gone to the bank and will be back soon.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“表达旅行经历并补充具体时间”写两至三句，再读给同伴听。至少使用一次have been to 与过去时间，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Have been to 表过去去过且已经返回；twice 说明经历次数，不给出具体已结束的日期。 Has gone to 表丽塔已经离开去银行；will be back soon 提示她尚未回来，soon 是未来时间提示。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 been/gone：去过且已回来，I have ___ to Vienna.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> been</p><p><strong>解析：</strong> 按本课规则判断：have been to 表示去过并已返回的经历；have gone to 通常表示去了且尚未返回。谈经验可用现在完成时，补充明确结束的日期或年份时通常改一般过去时。I have been to Rome 与 I went there in 2022 可在一段话中衔接。不能把现在完成时直接与 yesterday 等已结束时间机械拼接。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“我去过维也纳两次。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> I have been to Vienna twice.</p><p><strong>解析：</strong> Have been to 表过去去过且已经返回；twice 说明经历次数，不给出具体已结束的日期。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：Rita has gone to the bank and will be back soon.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 丽塔去银行了，很快就回来。</p><p><strong>解析：</strong> Has gone to 表丽塔已经离开去银行；will be back soon 提示她尚未回来，soon 是未来时间提示。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：have been to 与过去时间。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-084">上一课</a> · <a href="/life/english/new-concept/book-1/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-086">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const u=a(i,[["render",s]]);export{b as __pageData,u as default};
